#define PI 3.141592653589


// debugging params
//#define BGOPEN
//#define FGOPEN

// https://iquilezles.org/articles/distfunctions2d/
float sdOrientedVesica( vec2 p, vec2 a, vec2 b, float w )
{
    float r = 0.5*length(b-a);
    float d = 0.5*(r*r-w*w)/w;
    vec2 v = (b-a)/r;
    vec2 c = (b+a)*0.5;
    vec2 q = 0.5*abs(mat2(v.y,v.x,-v.x,v.y)*(p-c));
    vec3 h = (r*q.x<d*(q.y-r)) ? vec3(0.0,r,0.0) : vec3(-d,0.0,d+w);
    return length( q-h.xy) - h.z;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv0 = (fragCoord - 0.5*iResolution.xy) / iResolution.y;

    float bigEyeBlinkRate = 0.25;
    //bigEyeBlinkRate = 2.25;
    float smallEyeBlinkRate = 1.5;
    float bigEyeTheta = iTime*bigEyeBlinkRate;
    vec2 smush = vec2(0.85,0.35);
    vec2 _off = vec2(0.,0.);

    float nTiles = 10.;
    float cycle = mod(floor((bigEyeTheta - 3.*PI/2.) / (2.0*PI))+1.,4.)+1.;
//cycle = 5.;
    nTiles *= cycle;
//nTiles = 2.;
    if (iMouse.z>0.1) {
        nTiles = mix(1.,100.,iMouse.x/iResolution.x);
    }

    // make small eyes blink
    smallEyeBlinkRate *= cycle;
    vec2 uv = mod((uv0-_off)*nTiles, smush) - (smush/2.);
    uv *= 2.;
    float tinyBorderWidth = 50./nTiles;

    float blur0 = 1./iResolution.y;
    float blur = blur0 * nTiles;

    vec2 gid = floor((uv0-_off)*nTiles / smush) - (smush/2.);
    float blinkGID = ((mod(abs(gid.y)*0.9,2.))+(mod(abs(gid.x)*0.9,2.)));
    if ( mod(cycle, 6.) <= 3.1 ) blinkGID *= -1.;

    float theta = PI * blinkGID + smallEyeBlinkRate * iTime;
    float eyeW = 0.15 + 0.15 * sin(theta);
#ifdef BGOPEN
    eyeW = 0.3;
#endif
    float d = sdOrientedVesica(uv, vec2(-0.8,0.), vec2(0.8,0.), eyeW);
    vec3 col = vec3(0.);
    float eyeIntensity = 0.;
    float eyeBorder = 0.;
    if (eyeW >= 0.001) {
        eyeIntensity = 1.-smoothstep(-blur,blur,d);
        float a = 1.;
        float b = 1.+tinyBorderWidth;
        eyeBorder = 1.-smoothstep(-blur*a,blur*b,d)-smoothstep(blur*a,-blur*b,d);
    }

    // count valleys of eyeW sin wave
    // this increments when sin(theta)==-1 to change eye color when it is closed i.e. when eyeW==0
    float nCycles = floor((theta - 3.*PI/2.) / (2.0*PI));
    vec2 blockIndex = floor(gid*vec2(0.5,0.5));

    float irisColID = mod(blockIndex.x + blockIndex.y + nCycles, 2.0);
    float ballID = mod(min(abs(blockIndex.x), abs(blockIndex.y)) + nCycles, 2.0);
    //irisColID = 0.;

    // iris and eyeball colors
    vec3 irisColor = vec3(53., 136., 115.)/256.;
    if (irisColID<1.) irisColor = vec3(122., 229., 130.)/256.;
    vec3 ballC = vec3(0.5);
    if (ballID<1.) ballC = vec3(1.);

    float irisWidth = 0.4;
    d = distance(vec2(0.), uv);
    float irisIntensity = 1.-smoothstep(irisWidth-blur,irisWidth+blur,d);
    vec3 middleC = vec3(irisIntensity)*(1.-irisColor);

    // pupil
    middleC += 1.-smoothstep(0.15-blur, 0.15+blur, vec3(distance(vec2(0.), uv)));

    // eye outline color
    vec2 _uv = fract(uv0*2.)-0.5;
    float angle = atan(_uv.y, _uv.x);
    float radial = 0.5 + 0.5 * cos(length(uv0) * (50. + 10. * sin(iTime)) - iTime * 5. + sin(length(uv0) * 30.));
    float spinLines = 0.5 + 0.5 * sin(12. * sin(angle * 5.) + length(uv0) * 25. - iTime * 4.);
    vec3 rgbOutline = vec3(spinLines, 0., radial*0.75);

    // combine colors for background eyes
    vec3 colIn = eyeIntensity*(1.-middleC - (1.-irisIntensity)*(1.-ballC));
    colIn += eyeBorder*rgbOutline;

    // faint iris+pupil in big eye
    colIn *= (1.- ((1.-step(0.1, distance(uv0,vec2(0.))))  * 0.2));
    colIn *= (1.- ((1.-step(0.3, distance(uv0,vec2(0.))))  * 0.15));

    // large outer eye
    float bigEyeW = 0.2 + 0.2 * sin(bigEyeTheta);
    bigEyeW = max(0.0001, bigEyeW);
#ifdef FGOPEN
    bigEyeW = 0.75;
#endif
    d = sdOrientedVesica(uv0, vec2(-0.9,0.), vec2(0.9,0.), bigEyeW);
    float _blur = min(abs(blur0),abs(bigEyeW)); // fix wonky edges when closing
    float v = smoothstep(-_blur,_blur,d);

    // color outside
    vec3 colOut = vec3(1.);//mix(irisColor, vec3(0.), smoothstep(0.,4.,irisColID));
    //colOut = rgbOutline;

    // mix
    col = (1.-vec3(v))*colIn + vec3(v)*colOut;
    float a = 1.;
    float b = 9.;
    float bigEyeBorder = 1.-smoothstep(-blur0*a,blur0*b,d)-smoothstep(blur0*a,-blur0*b,d);
    col += vec3( bigEyeBorder ) * (0.5 + 0.5*cos(iTime+(uv0*50.).xyx+vec3(0,2,4)));

    // Output to screen
    fragColor = vec4(col,1.0);
}
